1	// SPDX-License-Identifier: BSD-3-Clause
2	// Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors
3	//! Physical frame allocator — 4 KiB granule, intrusive free list + per-region
4	//! bump pointers seeded from Limine's memmap.
5	//!
6	//! The allocator's state is just two pieces:
7	//!  - a `[Region; MAX_REGIONS]` array of `(base_pa, next_free_pa, end_pa)`
8	//!    bump pointers, one per `MEMMAP_USABLE` region Limine reported. `base_pa`
9	//!    is kept after init so `free_frame` can bounds-check freed PAs against
10	//!    the *original* extent, not the post-bump remainder;
11	//!  - a single free-list head pointer (kernel virtual address, HHDM-relative)
12	//!    of recently-freed frames.
13	//!
14	//! Allocation prefers the free list; if empty, bumps the first region with
15	//! room. Freed frames are pushed onto the free list — each frame's first
16	//! 8 bytes hold a pointer to the next free frame (the classic intrusive
17	//! free-list trick). This means each frame must be at least 8 bytes — which
18	//! is trivially true at 4 KiB.
19	//!
20	//! Capacity: MAX_REGIONS = 16 is enough for QEMU virt aarch64 (typically
21	//! 2–3 USABLE regions) and Apple Silicon QEMU (similar). If a board ever
22	//! reports more, `init_from_limine_memmap` panics with a clear message
23	//! pointing at this constant.
24	//!
25	//! Concurrency: single-threaded boot. The allocator is wrapped in an
26	//! `UnsafeCell` newtype with `unsafe impl Sync`, matching the convention
27	//! documented on [`crate::proc::table`]. Phase 3.2+'s page-fault flow runs
28	//! the allocator outside fault context — the handler sets `RTS_PAGEFAULT`
29	//! and returns to the scheduler, which then runs VM (or the kernel
30	//! resolver), which calls the allocator. The allocator therefore never
31	//! re-enters from an IRQ or fault.
32	
33	use core::cell::UnsafeCell;
34	use core::ptr;
35	
36	use crate::arch::aarch64::limine::{MEMMAP_USABLE, memmap_entries};
37	
38	/// 4 KiB page / frame size, in bytes.
39	pub const FRAME_SIZE: usize = 4096;
40	
41	/// Maximum number of `MEMMAP_USABLE` regions the allocator can track.
42	const MAX_REGIONS: usize = 16;
43	
44	/// Identifies one 4 KiB physical frame by its page-frame number (PA >> 12).
45	#[derive(Copy, Clone, PartialEq, Eq, Debug)]
46	pub struct Frame(u64);
47	
48	impl Frame {
49	    /// Construct from a physical address. The address must be 4 KiB-aligned
50	    /// — non-aligned values are rejected at construction so downstream
51	    /// callers can rely on `frame.addr()` returning an aligned PA.
52	    pub const fn from_addr(pa: u64) -> Self {
53	        assert!(
54	            pa & (FRAME_SIZE as u64 - 1) == 0,
55	            "Frame::from_addr: PA not 4 KiB aligned"
56	        );
57	        Self(pa >> 12)
58	    }
59	
60	    /// Physical address of this frame.
61	    pub const fn addr(self) -> u64 {
62	        self.0 << 12
63	    }
64	}
65	
66	#[derive(Copy, Clone)]
67	struct Region {
68	    /// First PA in this region, captured at init time. Stays fixed for the
69	    /// life of the allocator so `free_frame` can check `base_pa <= pa`
70	    /// against the region's *original* extent — `next_free_pa` advances on
71	    /// every bump, so it can't double as the lower bound.
72	    base_pa: u64,
73	    /// Next PA to hand out from this region; equals `base_pa` until the
74	    /// first allocation, then advances toward `end_pa`.
75	    next_free_pa: u64,
76	    /// One-past-the-last PA in this region.
77	    end_pa: u64,
78	}
79	
80	const EMPTY_REGION: Region = Region {
81	    base_pa: 0,
82	    next_free_pa: 0,
83	    end_pa: 0,
84	};
85	
86	struct Allocator {
87	    regions: [Region; MAX_REGIONS],
88	    region_count: usize,
89	    /// Head of the free list, as an HHDM virtual address (so we can deref
90	    /// it directly without redoing the HHDM math on each `alloc_frame`).
91	    /// `null` means the free list is empty.
92	    free_head: *mut FreeNode,
93	    /// Statistics for diagnostics — incremented on every alloc/free.
94	    allocs: u64,
95	    frees: u64,
96	}
97	
98	#[repr(C)]
99	struct FreeNode {
100	    next: *mut FreeNode,
101	}
102	
103	#[repr(transparent)]
104	struct AllocatorCell(UnsafeCell<Allocator>);
105	// SAFETY: single-threaded boot invariant; see module-level comment.
106	unsafe impl Sync for AllocatorCell {}
107	
108	static ALLOC: AllocatorCell = AllocatorCell(UnsafeCell::new(Allocator {
109	    regions: [EMPTY_REGION; MAX_REGIONS],
110	    region_count: 0,
111	    free_head: ptr::null_mut(),
112	    allocs: 0,
113	    frees: 0,
114	}));
115	
116	/// Populate the allocator from Limine's memmap. Must be called once during
117	/// boot, before any [`alloc_frame`] / [`free_frame`] call.
118	///
119	/// `hhdm_offset` is Limine's HHDM offset (also passed to
120	/// [`crate::mm::set_hhdm_offset`] separately so the allocator can dereference
121	/// freed-frame pointers into a kernel VA).
122	///
123	/// SAFETY: must be called exactly once, single-threaded, after
124	/// [`crate::mm::set_hhdm_offset`].
125	pub unsafe fn init_from_limine_memmap() {
126	    let entries = memmap_entries().expect("Limine did not populate the memmap response");
127	
128	    // SAFETY: single-threaded boot, single writer.
129	    let a = unsafe { &mut *ALLOC.0.get() };
130	
131	    for entry in entries {
132	        if entry.kind != MEMMAP_USABLE {
133	            continue;
134	        }
135	        // Limine guarantees USABLE entries are 4 KiB-aligned in both base
136	        // and length — verify rather than silently dropping bytes.
137	        let base = entry.base;
138	        let len = entry.length;
139	        assert!(
140	            base & (FRAME_SIZE as u64 - 1) == 0,
141	            "Limine USABLE base {base:#x} is not 4 KiB-aligned"
142	        );
143	        assert!(
144	            len & (FRAME_SIZE as u64 - 1) == 0,
145	            "Limine USABLE length {len:#x} is not 4 KiB-aligned"
146	        );
147	        if len == 0 {
148	            continue;
149	        }
150	        assert!(
151	            a.region_count < MAX_REGIONS,
152	            "Limine reported more than MAX_REGIONS={MAX_REGIONS} usable regions; \
153	             grow the constant in mm::frame"
154	        );
155	        a.regions[a.region_count] = Region {
156	            base_pa: base,
157	            next_free_pa: base,
158	            end_pa: base.checked_add(len).expect("USABLE region overflows u64"),
159	        };
160	        a.region_count += 1;
161	    }
162	
163	    assert!(
164	        a.region_count > 0,
165	        "Limine memmap contains no MEMMAP_USABLE regions"
166	    );
167	}
168	
169	/// Allocate one 4 KiB frame. Returns `None` if no physical memory remains
170	/// (both the free list and every bump region are exhausted).
171	pub fn alloc_frame() -> Option<Frame> {
172	    // SAFETY: single-threaded boot invariant; see module-level comment.
173	    let a = unsafe { &mut *ALLOC.0.get() };
174	
175	    // Free list takes priority — recently freed frames are still cache-hot.
176	    if !a.free_head.is_null() {
177	        // SAFETY: free_head is either null or an HHDM-VA pointer we set on a
178	        // previous `free_frame`. Reading the first 8 bytes of a free frame
179	        // through HHDM is sound because the frame is unmapped from all
180	        // address spaces (free means free) and HHDM is the only mapping.
181	        let node = a.free_head;
182	        let next = unsafe { (*node).next };
183	        a.free_head = next;
184	        a.allocs += 1;
185	        let pa = hhdm_vaddr_to_pa(node as u64);
186	        // Zero on the way out, same contract as the bump path below. A
187	        // free-list frame still holds the previous owner's bytes, and callers
188	        // depend on a clean frame: `addrspace::ensure_next_table` builds
189	        // intermediate page tables expecting all-invalid entries, and
190	        // `VMCTL_PT_MAP` hands the frame straight to EL0. Without this, a
191	        // reused frame would seed page tables with garbage PTEs and leak one
192	        // address space's data into another. `next` is already captured above,
193	        // so wiping the intrusive node here is fine.
194	        // SAFETY: HHDM covers this PA (Limine base revision 2 blanket-maps
195	        // [0, 4 GiB)), the frame is exclusively ours now, and HHDM is cacheable
196	        // normal memory — no MMIO side-channel that would require
197	        // `write_volatile`.
198	        unsafe {
199	            ptr::write_bytes(crate::mm::phys_to_hhdm(pa), 0, FRAME_SIZE);
200	        }
201	        return Some(Frame::from_addr(pa));
202	    }
203	
204	    // Otherwise bump from the first region with room.
205	    for r in &mut a.regions[..a.region_count] {
206	        if r.next_free_pa < r.end_pa {
207	            let pa = r.next_free_pa;
208	            r.next_free_pa += FRAME_SIZE as u64;
209	            a.allocs += 1;
210	            // Zero before hand-out, same as the free-list path above, so every
211	            // frame `alloc_frame` returns is clean. Page-table walkers expect
212	            // intermediate tables to start all-invalid, and zero pages are
213	            // what user-mode brk/mmap expects too. Cost: one 4 KiB memset,
214	            // amortized over the frame's lifetime.
215	            // SAFETY: HHDM covers this PA (Limine base revision 2 blanket-maps
216	            // [0, 4 GiB)), the frame is exclusively ours, and HHDM is
217	            // cacheable normal memory — no MMIO side-channel that would
218	            // require `write_volatile`.
219	            unsafe {
220	                ptr::write_bytes(crate::mm::phys_to_hhdm(pa), 0, FRAME_SIZE);
221	            }
222	            return Some(Frame::from_addr(pa));
223	        }
224	    }
225	    None
226	}
227	
228	/// Return one 4 KiB frame to the allocator. The frame is pushed onto the
229	/// free list; future `alloc_frame` calls will hand it back out (zeroed —
230	/// we re-zero on the alloc side, not the free side, so callers can free
231	/// without thinking about residual state).
232	///
233	/// Panics if `frame` lies outside the union of all tracked regions — that
234	/// would mean a caller forged a frame from a non-USABLE PA (e.g. a kernel-image
235	/// PA from `EXECUTABLE_AND_MODULES`, or a gap between two USABLE regions).
236	///
237	/// **Precondition (not checked):** the same frame must not be freed twice.
238	/// A double free silently corrupts the free list — the intrusive `next`
239	/// pointer on the freed frame gets overwritten with the previous head, and
240	/// the next two `alloc_frame` calls hand out the same PA. Detecting at
241	/// runtime would require an O(n) free-list walk per free (or extra
242	/// per-frame state); both are overkill for a single-threaded boot
243	/// allocator. The bounds check below catches forged-PA cases but cannot
244	/// distinguish a legitimate frame from one already on the list.
245	pub fn free_frame(frame: Frame) {
246	    let pa = frame.addr();
247	
248	    // SAFETY: single-threaded boot invariant.
249	    let a = unsafe { &mut *ALLOC.0.get() };
250	
251	    // Bounds-check against tracked regions. `base_pa` is captured at init
252	    // time and never advances, so `[base_pa, end_pa)` is the region's
253	    // original extent — exactly the set of legal frame PAs.
254	    let mut in_range = false;
255	    for r in &a.regions[..a.region_count] {
256	        if r.base_pa <= pa && pa < r.end_pa {
257	            in_range = true;
258	            break;
259	        }
260	    }
261	    assert!(
262	        in_range,
263	        "free_frame: PA {pa:#x} is outside all USABLE regions"
264	    );
265	
266	    // Push onto the free list via HHDM.
267	    let vaddr = crate::mm::phys_to_hhdm(pa) as *mut FreeNode;
268	    // SAFETY: the frame is now owned by the allocator (caller relinquishes
269	    // it). HHDM mapping guarantees the VA is readable+writable.
270	    unsafe {
271	        (*vaddr).next = a.free_head;
272	    }
273	    a.free_head = vaddr;
274	    a.frees += 1;
275	}
276	
277	fn hhdm_vaddr_to_pa(vaddr: u64) -> u64 {
278	    // HHDM is a flat shift; reversing is sub.
279	    vaddr - crate::mm::hhdm_offset()
280	}
