57	/// A server request band: base constant, its members, and the count constant
58	/// that bounds it (`None` for VM, which has no `NR_*` on the Rust side).
59	///
60	/// `members` is checked against `count` by
61	/// `every_band_member_list_matches_its_count`: a new request that bumps the Rust
62	/// `NR_*` without gaining a row here would otherwise render a larger count and
63	/// no macro for the request itself.
64	struct Band {
65	    title: &'static str,
66	    base_name: &'static str,
67	    base: i32,
68	    count: Option<(&'static str, usize)>,
69	    members: Vec<(&'static str, i32)>,
70	}
71	
