137	/// Render `minix/callnr.h`.
138	pub fn render() -> String {
139	    let mut f = CFile::new(
140	        "Kernel-call numbers, server request bands, and their payload constants.",
141	        &["kernel-shared/src/callnr.rs"],
142	    );
143	    f.guard_open(GUARD);
144	
145	    f.blank();
146	    f.include(
147	        "minix/ipc.h",
148	        "NOTIFY_MESSAGE, for the band ordering checks",
149	    );
150	
151	    f.block_comment(&[
152	        "Deviation from MINIX 3: its <minix/callnr.h> holds POSIX syscall numbers",
153	        "and keeps server request numbers in <minix/com.h>. minix.rs has no POSIX",
154	        "call-number layer -- a libc wrapper builds a server request directly --",
155	        "so this header carries the kernel calls and the request bands together.",
156	        "",
157	        "Payload byte offsets are not emitted yet: on the Rust side they live in",
158	        "doc comments rather than constants. The first musl wrapper (slice 5.6) is",
159	        "the forcing function for promoting them to real constants.",
160	    ]);
161	
162	    f.section("kernel calls");
163	    f.define_hex("KERNEL_CALL", callnr::KERNEL_CALL.into());
164	    f.blank();
165	    for (name, value) in kernel_calls() {
166	        f.define_hex(name, value.into());
167	    }
168	    f.blank();
169	    // Name-matched with the Rust constant as of slice 5.1 (it was
170	    // `NR_KERN_CALLS_PHASE4` there, and carried a provenance comment here to
171	    // bridge the gap). Keep the two spellings identical past the 5.6 ABI
172	    // freeze — `nr_kern_calls_is_not_phase_suffixed` guards it.
173	    f.define_dec("NR_KERN_CALLS", callnr::NR_KERN_CALLS as i64);
174	    f.define_dec("NR_SYS_CALLS", callnr::NR_SYS_CALLS as i64);
175	
176	    f.section("kernel-call payload constants");
177	    f.define_dec("GET_WHOAMI", callnr::GET_WHOAMI.into());
178	    f.define_dec("SYS_GETINFO_NAME_LEN", callnr::SYS_GETINFO_NAME_LEN as i64);
179	    f.define_dec("EXEC_NAME_LEN", callnr::EXEC_NAME_LEN as i64);
180	    f.define_dec("PRIVCTL_SET_USER", callnr::PRIVCTL_SET_USER.into());
181	    f.define_dec("SCHEDCTL_FLAG_KERNEL", callnr::SCHEDCTL_FLAG_KERNEL.into());
182	
183	    f.section("SYS_DIAGCTL subcodes + inline-text payload");
184	    f.define_dec("DIAGCTL_CODE_DIAG", callnr::DIAGCTL_CODE_DIAG.into());
185	    f.define_dec(
186	        "DIAGCTL_CODE_STACKTRACE",
187	        callnr::DIAGCTL_CODE_STACKTRACE.into(),
188	    );
189	    f.define_dec(
190	        "DIAGCTL_CODE_REGISTER",
191	        callnr::DIAGCTL_CODE_REGISTER.into(),
192	    );
193	    f.define_dec(
194	        "DIAGCTL_CODE_UNREGISTER",
195	        callnr::DIAGCTL_CODE_UNREGISTER.into(),
196	    );
197	    f.define_dec("DIAG_TEXT_OFF", callnr::DIAG_TEXT_OFF as i64);
198	    f.define_dec("DIAG_TEXT_MAX", callnr::DIAG_TEXT_MAX as i64);
199	
200	    f.section("grants: SYS_SETGRANT / SYS_SAFECOPY");
201	    f.block_comment(&[
202	        "The grant ABI (slice 5.2). The grant-entry layout itself is deliberately",
203	        "not emitted yet: no C consumes it before the musl slice, and a dedicated",
204	        "<minix/safecopies.h> would need its own builder and CI syntax check. The",
205	        "flag values and the id packing are here because a C caller needs them to",
206	        "read a grant id out of a message payload.",
207	    ]);
208	    f.define_dec("SAFECOPY_FROM", callnr::SAFECOPY_FROM.into());
209	    f.define_dec("SAFECOPY_TO", callnr::SAFECOPY_TO.into());
210	    f.blank();
211	    for (name, value) in cpf_flags() {
212	        f.define_hex(name, value.into());
213	    }
214	    f.blank();
215	    f.define_dec("GRANT_SHIFT", grant::GRANT_SHIFT.into());
216	    f.define_hex("GRANT_MAX_IDX", grant::GRANT_MAX_IDX.into());
217	    f.define_hex("GRANT_MAX_SEQ", grant::GRANT_MAX_SEQ.into());
218	    f.define_dec("GRANT_INVALID", grant::GRANT_INVALID.into());
219	    f.blank();
220	    f.define_raw(
221	        "GRANT_ID(idx, seq)",
222	        "((int) ((((unsigned) (seq) & GRANT_MAX_SEQ) << GRANT_SHIFT) \\\n                                 | ((unsigned) (idx) & GRANT_MAX_IDX)))",
223	    );
224	    f.define_raw("GRANT_IDX(g)", "((unsigned) (g) & GRANT_MAX_IDX)");
225	    f.define_raw(
226	        "GRANT_SEQ(g)",
227	        "(((unsigned) (g) >> GRANT_SHIFT) & GRANT_MAX_SEQ)",
228	    );
229	    f.define_raw("GRANT_VALID(g)", "((g) >= 0)");
230	    f.blank();
231	    // Check the C packing against the Rust one rather than trusting that the
232	    // two expressions were transcribed the same way.
233	    f.static_assert(
234	        &format!(
235	            "GRANT_ID(GRANT_MAX_IDX, GRANT_MAX_SEQ) == {}",
236	            grant::grant_id(grant::GRANT_MAX_IDX, grant::GRANT_MAX_SEQ)
237	        ),
238	        "the C grant-id packing disagrees with the Rust one",
239	    );
240	    f.static_assert(
241	        &format!("GRANT_IDX({GRANT_PROBE_ID}) == {GRANT_PROBE_IDX}"),
242	        "GRANT_IDX does not invert GRANT_ID",
243	    );
244	    f.static_assert(
245	        &format!("GRANT_SEQ({GRANT_PROBE_ID}) == {GRANT_PROBE_SEQ}"),
246	        "GRANT_SEQ does not invert GRANT_ID",
247	    );
248	
249	    f.section("SYS_VMCTL subcalls");
250	    f.define_dec("VMCTL_PT_MAP", callnr::VMCTL_PT_MAP.into());
251	    f.define_dec("VMCTL_PT_UNMAP", callnr::VMCTL_PT_UNMAP.into());
252	    f.define_dec(
253	        "VMCTL_CLEAR_PAGEFAULT",
254	        callnr::VMCTL_CLEAR_PAGEFAULT.into(),
255	    );
256	    f.define_dec("VMCTL_GET_PAGEFAULT", callnr::VMCTL_GET_PAGEFAULT.into());
257	    f.define_dec("VMCTL_VMINHIBIT_SET", callnr::VMCTL_VMINHIBIT_SET.into());
258	    f.define_dec(
259	        "VMCTL_VMINHIBIT_CLEAR",
260	        callnr::VMCTL_VMINHIBIT_CLEAR.into(),
261	    );
262	    f.define_dec("NR_VMCTL_SUBCALLS", callnr::NR_VMCTL_SUBCALLS as i64);
263	    f.blank();
264	    f.define_dec("VMCTL_PROT_WRITE", callnr::VMCTL_PROT_WRITE.into());
265	    f.define_dec("VMCTL_PROT_EXEC", callnr::VMCTL_PROT_EXEC.into());
266	
267	    for band in bands() {
268	        f.section(band.title);
269	        f.define_hex(band.base_name, band.base.into());
270	        for (name, value) in &band.members {
271	            f.define_hex(name, (*value).into());
272	        }
273	        if let Some((count_name, count)) = band.count {
274	            f.define_dec(count_name, count as i64);
275	        }
276	    }
277	
278	    f.section("band ordering");
279	    f.block_comment(&[
280	        "Mirrors the `const _: () = assert!(..)` guards in callnr.rs: every band",
281	        "sits above the previous one and entirely below NOTIFY_MESSAGE, so no",
282	        "server request can ever be mistaken for a kernel NOTIFY.",
283	    ]);
284	    f.static_assert(
285	        "NR_SYS_CALLS >= NR_KERN_CALLS",
286	        "the privilege call mask is narrower than the kernel-call set",
287	    );
288	    f.static_assert(
289	        "PM_RQ_BASE > KERNEL_CALL + NR_KERN_CALLS - 1",
290	        "the PM band overlaps the kernel calls",
291	    );
292	    f.static_assert(
293	        "PM_RQ_BASE + NR_PM_MSGS - 1 < VM_RQ_BASE",
294	        "the PM band overlaps the VM band",
295	    );
296	    f.static_assert("SEF_RQ_BASE > VM_FORK", "the SEF band overlaps the VM band");
297	    f.static_assert(
298	        "DS_RQ_BASE > SEF_RQ_BASE + NR_SEF_MSGS - 1",
299	        "the DS band overlaps the SEF band",
300	    );
301	    f.static_assert(
302	        "SCHED_RQ_BASE > DS_RQ_BASE + NR_DS_REQUESTS - 1",
303	        "the SCHED band overlaps the DS band",
304	    );
305	    f.static_assert(
306	        "SCHED_RQ_BASE + NR_SCHED_MSGS - 1 < NOTIFY_MESSAGE",
307	        "a server request number collides with NOTIFY_MESSAGE",
308	    );
309	
310	    f.guard_close(GUARD);
311	    f.finish()
312	}
