3	//! Fault-safe access to user memory (slice 5.1, decision D5).
4	//!
5	//! Every byte the kernel moves in or out of a user address space goes through
6	//! here. The kernel **never dereferences a user VA directly** — not even the
7	//! active TTBR0's. Instead it walks the target's page tables
8	//! ([`walk_pt_in`]) and copies through the frame's HHDM alias.
9	//!
10	//! Two properties fall out of that, and both are the point:
11	//!
12	//! - **An unmapped page is a walk miss, not an exception.** It returns
13	//!   [`EFAULT`] to the caller instead of taking an EL1 data abort that the
14	//!   same-EL vector would turn into a kernel panic. No exception-fixup table
15	//!   (Linux's `extable`) is needed or wanted — see D5's rejected alternative.
16	//! - **The target need not be the running process.** The walk is
17	//!   address-space-independent, so the deferred `MF_DELIVERMSG` flush can write
18	//!   a *receiver's* buffer without that receiver's TTBR0 being installed.
19	//!
20	//! A read-only destination is rejected explicitly ([`Prot::writable`]): the
21	//! HHDM alias is a kernel mapping, so the MMU's EL0 permission bits do not
22	//! police these writes the way they policed the old `write_volatile`.
23	//!
24	//! Slice 5.2's grant engine (`SYS_SAFECOPY` / `SYS_COPY`) is built directly on
25	//! these primitives: [`copy_between_as`] is two walks and a `memcpy` per chunk,
26	//! with no new mechanism of its own.
27	
28	use minixrs_kernel_shared::error::EFAULT;
29	use minixrs_kernel_shared::message::{USER_PAGE_SIZE, dual_page_chunks, page_chunks};
30	
31	use crate::arch::aarch64::addrspace::walk_pt_in;
32	use crate::mm::{FRAME_SIZE, phys_to_hhdm};
33	
34	// `page_chunks` splits at `USER_PAGE_SIZE` boundaries and `walk_pt_in` resolves
35	// one L3 leaf per chunk, so the two granules must be the same number. They are
36	// declared in different crates — `USER_PAGE_SIZE` in `kernel-shared` (to keep
37	// the chunk arithmetic host-testable), `FRAME_SIZE` in the kernel's allocator —
38	// so nothing but this assert stops a future granule change from desyncing them
39	// into silent partial copies.
40	const _: () = assert!(USER_PAGE_SIZE == FRAME_SIZE as u64);
41	
42	/// Copy `dst.len()` bytes out of address space `ttbr0_pa`, starting at user
43	/// VA `va`.
44	///
45	/// `Err(EFAULT)` if any page of the range is unmapped. `dst` may hold a
46	/// partial copy on error; every caller discards its staging buffer in that
47	/// case, so no rollback is done (MINIX 3's `data_copy` has the same contract).
48	pub fn copy_from_user_as(ttbr0_pa: u64, va: u64, dst: &mut [u8]) -> Result<(), i32> {
49	    let mut done = 0usize;
50	    for chunk in page_chunks(va, dst.len()) {
51	        let (pa, _prot) = walk_pt_in(ttbr0_pa, chunk.page_va).ok_or(EFAULT)?;
52	        // SAFETY: `pa` is a frame this address space's L3 maps, so it came from
53	        // `alloc_frame` and is HHDM-mapped; `chunk.offset + chunk.len` is
54	        // within one 4 KiB page by `page_chunks`' contract, so the source range
55	        // lies inside that frame. The HHDM alias and the TTBR0 mapping are both
56	        // Normal-WB Inner-Shareable (`ATTR_IDX_NORMAL`) and ARMv8 data caches
57	        // are PIPT, so the two aliases are coherent with no maintenance — the
58	        // same assumption `addrspace::table_ref` already makes for live page
59	        // tables. Single-threaded EL1 with DAIF.I masked: no concurrent unmap
60	        // can race the walk. `dst` is a distinct kernel buffer, never a HHDM
61	        // alias of the same frame, so the ranges cannot overlap.
62	        unsafe {
63	            let src = phys_to_hhdm(pa).add(chunk.offset);
64	            core::ptr::copy_nonoverlapping(src, dst.as_mut_ptr().add(done), chunk.len);
65	        }
66	        done += chunk.len;
67	    }
68	    Ok(())
69	}
70	
71	/// Copy `src` into address space `ttbr0_pa` at user VA `va`.
72	///
73	/// `Err(EFAULT)` if any page of the range is unmapped or not EL0-writable.
74	/// **All-or-nothing**: every page is probed before the first byte is written,
75	/// so a straddling buffer whose second page is bad leaves the user's memory
76	/// untouched rather than half-updated. A 104-byte `Message` is only 8-aligned
77	/// and really can straddle, so this matters in practice.
78	pub fn copy_to_user_as(ttbr0_pa: u64, va: u64, src: &[u8]) -> Result<(), i32> {
79	    probe_user_range(ttbr0_pa, va, src.len(), true)?;
80	
81	    let mut done = 0usize;
82	    for chunk in page_chunks(va, src.len()) {
83	        let (pa, _prot) = walk_pt_in(ttbr0_pa, chunk.page_va).ok_or(EFAULT)?;
84	        // SAFETY: as `copy_from_user_as`, with the direction reversed — and the
85	        // destination additionally proven EL0-writable by the probe above, so
86	        // this cannot smuggle a write past a read-only mapping via the HHDM.
87	        unsafe {
88	            let dst = phys_to_hhdm(pa).add(chunk.offset);
89	            core::ptr::copy_nonoverlapping(src.as_ptr().add(done), dst, chunk.len);
90	        }
91	        done += chunk.len;
92	    }
93	    Ok(())
94	}
95	
96	/// Copy `len` bytes from `src_va` in address space `src_ttbr0` to `dst_va` in
97	/// address space `dst_ttbr0`.
98	///
99	/// The grant engine's whole mechanism (slice 5.2): two page-table walks and a
100	/// `memcpy` through the frames' HHDM aliases, per chunk. Neither address space
101	/// need be the active one, and the two may be the same.
102	///
103	/// `Err(EFAULT)` if any page of either range is unmapped, or any destination
104	/// page is not EL0-writable. **All-or-nothing on the destination**: both ranges
105	/// are probed before the first byte moves, the same contract (and for the same
106	/// reason) as [`copy_to_user_as`] — and the destination probe is load-bearing
107	/// for the same reason too, since the HHDM alias is a kernel mapping that the
108	/// MMU's EL0 permission bits do not police.
109	///
110	/// Overlapping ranges within one address space are copied chunk-by-chunk in
111	/// ascending order with `memmove` semantics per chunk. That is well-defined for
112	/// disjoint or forward-shifted ranges but is *not* a general overlap-safe copy;
113	/// no caller asks for one (a grant names one process's buffer and the caller's
114	/// own, and `SYS_COPY`'s two endpoints are distinct in every use).
115	pub fn copy_between_as(
116	    src_ttbr0: u64,
117	    src_va: u64,
118	    dst_ttbr0: u64,
119	    dst_va: u64,
120	    len: usize,
121	) -> Result<(), i32> {
122	    probe_user_range(src_ttbr0, src_va, len, false)?;
123	    probe_user_range(dst_ttbr0, dst_va, len, true)?;
124	
125	    for chunk in dual_page_chunks(src_va, dst_va, len) {
126	        let (src_pa, _prot) = walk_pt_in(src_ttbr0, chunk.src_page_va).ok_or(EFAULT)?;
127	        let (dst_pa, _prot) = walk_pt_in(dst_ttbr0, chunk.dst_page_va).ok_or(EFAULT)?;
128	        // SAFETY: both PAs came from an L3 leaf of their respective address
129	        // space, so both are `alloc_frame` frames and HHDM-mapped; each
130	        // `offset + len` stays inside one 4 KiB page by `dual_page_chunks`'
131	        // contract, so both ranges lie inside their frame. Cache coherence and
132	        // the single-threaded-EL1 no-concurrent-unmap argument are as in
133	        // `copy_from_user_as`. `copy` (not `copy_nonoverlapping`) because the
134	        // two aliases *can* name the same frame when a caller copies within one
135	        // address space.
136	        unsafe {
137	            let src = phys_to_hhdm(src_pa).add(chunk.src_offset);
138	            let dst = phys_to_hhdm(dst_pa).add(chunk.dst_offset);
139	            core::ptr::copy(src, dst, chunk.len);
140	        }
141	    }
142	    Ok(())
143	}
144	
145	/// Verify every page of `[va, va + len)` is mapped in `ttbr0_pa` — and
146	/// EL0-writable when `write`.
147	///
148	/// The pre-pass behind [`copy_to_user_as`]'s and [`copy_between_as`]'s
149	/// all-or-nothing contracts, exposed because a caller sometimes wants the check
150	/// without the copy.
151	pub fn probe_user_range(ttbr0_pa: u64, va: u64, len: usize, write: bool) -> Result<(), i32> {
152	    for chunk in page_chunks(va, len) {
153	        let (_pa, prot) = walk_pt_in(ttbr0_pa, chunk.page_va).ok_or(EFAULT)?;
154	        if write && !prot.writable {
155	            return Err(EFAULT);
156	        }
157	    }
158	    Ok(())
159	}
160

180	        p.regs.x[0] = EDEADSRCDST as i64 as u64;
181	        p.q_link = None;
182	        p.sendto_e = NONE;
183	        p.getfrom_e = NONE;
184	        p.misc_flags &= !MF_REPLY_PEND;
185	        // SAFETY: single-threaded EL1 context; the exclusive `p` borrow ends
186	        // (NLL) as `rts_unset` captures `nr` internally — it enqueues the
187	        // proc if the IPC bits were its only block state.
188	        unsafe { sched::rts_unset(p, RTS_SENDING | RTS_RECEIVING) };
189	    }
190	    // Every sender the loop woke was on the dead proc's caller_q; the chain
191	    // is now meaningless, so drop the head.
192	    proc_table[target_idx].caller_q = None;
193	
194	    if let Some(pid) = dead_priv_id {
195	        let pidx = pid.as_usize();
196	        if pidx < NR_SYS_PROCS && priv_table[pidx].proc_nr == Some(dead_nr) {
197	            for pv in priv_table.iter_mut() {
198	                clear_sys_bit(&mut pv.notify_pending, pid);
199	            }
200	            priv_table[pidx].notify_pending = [0; IPC_MAP_CHUNKS];
201	            // Drop the grant-table registration (slice 5.2). The address named
202	            // a table in the address space just torn down; leaving it would let
203	            // a *recycled* slot's new occupant inherit a table address it never
204	            // registered, and `verify_grant` would read grant entries out of
205	            // whatever now lives there.
206	            priv_table[pidx].grant_table = 0;
207	            priv_table[pidx].grant_entries = 0;
208	            priv_table[pidx].proc_nr = None;
209	        }
210	    }
