// SPDX-License-Identifier: BSD-3-Clause
// Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors
//! Native-endian scalar accessors for a [`Message`] payload.
//!
//! Every server and driver marshals its requests by hand — there is no typed
//! message-union layer in minix.rs (MINIX 3's `m1`/`m2`/… structs), because a
//! payload offset is documented per request in `kernel-shared::callnr` and
//! reading it by offset keeps the ABI in one place. What that leaves is these
//! four one-line accessors, which had been copied into PM, VFS, VM, DS, and
//! SCHED. Slice 5.3 lifted them here rather than copy them a sixth time into
//! `drivers/tty`.
//!
//! Native-endian on purpose: both ends of every message are the same machine, and
//! the generated C headers describe the payload as raw bytes at an offset. There
//! is no wire format to agree on.
//!
//! Out-of-range offsets and short slices are handled by returning `0` / writing
//! nothing rather than panicking. A server has no business dying on a malformed
//! request from a client it does not trust, and `0` is a value every request's
//! own validation already has to reject (endpoint `NONE` is `0`, grant id `0` has
//! sequence 0, length `0` is a no-op).

use minixrs_kernel_shared::Message;

/// Read a native-endian `i32` from payload `off..off+4`. Returns `0` if the range
/// does not fit the payload.
pub fn rd_i32(m: &Message, off: usize) -> i32 {
    match m.payload.get(off..off + 4) {
        Some(b) => i32::from_ne_bytes(b.try_into().unwrap_or([0; 4])),
        None => 0,
    }
}

/// Write a native-endian `i32` into payload `off..off+4`. No-op if the range does
/// not fit the payload.
pub fn wr_i32(m: &mut Message, off: usize, v: i32) {
    if let Some(b) = m.payload.get_mut(off..off + 4) {
        b.copy_from_slice(&v.to_ne_bytes());
    }
}

/// Read a native-endian `u64` from payload `off..off+8`. Returns `0` if the range
/// does not fit the payload.
pub fn rd_u64(m: &Message, off: usize) -> u64 {
    match m.payload.get(off..off + 8) {
        Some(b) => u64::from_ne_bytes(b.try_into().unwrap_or([0; 8])),
        None => 0,
    }
}

/// Write a native-endian `u64` into payload `off..off+8`. No-op if the range does
/// not fit the payload.
pub fn wr_u64(m: &mut Message, off: usize, v: u64) {
    if let Some(b) = m.payload.get_mut(off..off + 8) {
        b.copy_from_slice(&v.to_ne_bytes());
    }
}

/// The address of a local staging buffer, in the form the kernel's copy calls
/// want it (`SYS_COPY` / `SYS_SAFECOPY` take a plain `u64` VA).
///
/// `&mut` rather than `&`: the kernel writes through *its own* mapping of this
/// frame (the HHDM alias), not through this pointer, so the borrow checker cannot
/// see the write. Requiring an exclusive borrow is what stops a caller handing
/// over a buffer it is simultaneously reading. The SENDREC's inline asm is a full
/// memory clobber, so the compiler cannot cache the buffer's contents across the
/// call either.
pub fn buf_addr(b: &mut [u8]) -> u64 {
    b.as_mut_ptr() as usize as u64
}

#[cfg(test)]
mod tests {
    use super::*;

    fn msg() -> Message {
        Message {
            m_source: 0,
            m_type: 0,
            payload: [0u8; 96],
        }
    }

    #[test]
    fn i32_round_trips_at_every_documented_offset() {
        // The offsets real requests use: 0/4/8/12 (i32 words) and 16 (where the
        // u64 fields start).
        for off in [0usize, 4, 8, 12, 16] {
            let mut m = msg();
            wr_i32(&mut m, off, -12345);
            assert_eq!(rd_i32(&m, off), -12345, "offset {off}");
        }
    }

    #[test]
    fn u64_round_trips() {
        for off in [0usize, 8, 16, 24, 32, 88] {
            let mut m = msg();
            wr_u64(&mut m, off, 0xDEAD_BEEF_CAFE_F00D);
            assert_eq!(rd_u64(&m, off), 0xDEAD_BEEF_CAFE_F00D, "offset {off}");
        }
    }

    #[test]
    fn writes_do_not_disturb_neighbouring_fields() {
        let mut m = msg();
        wr_i32(&mut m, 0, 1);
        wr_i32(&mut m, 4, 2);
        wr_i32(&mut m, 8, 3);
        wr_u64(&mut m, 16, 4);
        assert_eq!((rd_i32(&m, 0), rd_i32(&m, 4), rd_i32(&m, 8)), (1, 2, 3));
        assert_eq!(rd_u64(&m, 16), 4);
        // Nothing leaked into the gap at 12..16 or past the u64.
        assert_eq!(rd_i32(&m, 12), 0);
        assert_eq!(rd_u64(&m, 24), 0);
    }

    /// A malformed request must not be able to kill a server. The last legal
    /// offsets are 92 for an i32 and 88 for a u64; one past each must be inert.
    #[test]
    fn out_of_range_offsets_are_inert_not_panics() {
        let mut m = msg();
        wr_i32(&mut m, 92, 7);
        assert_eq!(rd_i32(&m, 92), 7, "92..96 is the last legal i32 slot");
        wr_u64(&mut m, 88, 9);
        assert_eq!(rd_u64(&m, 88), 9, "88..96 is the last legal u64 slot");

        let before = m.payload;
        wr_i32(&mut m, 93, 1);
        wr_u64(&mut m, 89, 1);
        wr_i32(&mut m, usize::MAX, 1);
        wr_u64(&mut m, usize::MAX, 1);
        assert_eq!(m.payload, before, "an out-of-range write must change nothing");

        assert_eq!(rd_i32(&m, 93), 0);
        assert_eq!(rd_u64(&m, 89), 0);
        assert_eq!(rd_i32(&m, usize::MAX), 0);
        assert_eq!(rd_u64(&m, usize::MAX), 0);
    }

    #[test]
    fn buf_addr_reports_the_buffers_own_address() {
        let mut buf = [0u8; 16];
        let want = buf.as_mut_ptr() as usize as u64;
        assert_eq!(buf_addr(&mut buf), want);
        assert_ne!(buf_addr(&mut buf), 0);
    }
}

// SPDX-License-Identifier: BSD-3-Clause
// Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors
//! Kernel-call clients for the cross-address-space copy engine (slice 5.2's
//! `SYS_SAFECOPY` / `SYS_COPY`).
//!
//! Lifted out of PM in slice 5.3, when the TTY driver became the second holder of
//! `SYS_SAFECOPY` and the marshaling would otherwise have been copied verbatim.
//! The payload layouts are documented on the two constants in
//! `kernel-shared::callnr`; this module is the single place they are written.
//!
//! Like [`crate::sef`], [`crate::ds`], and [`crate::diag`], these issue IPC traps,
//! so the module is excluded from host coverage and verified through the kernel's
//! `[ksys SYS_SAFECOPY]` / `[ksys SYS_COPY]` boot traces.
//!
//! ## The confused-deputy rule
//!
//! A server that holds these calls and serves clients that do not must take the
//! **granter from the kernel-stamped `m_source`**, never from a request payload. A
//! caller-supplied granter endpoint would let any client aim a privileged
//! cross-address-space copy at a third party's memory *through* the server. These
//! functions cannot enforce that — the granter is a parameter — so it is the
//! caller's obligation, and it binds every grant-id-carrying request in the CDEV,
//! BDEV, and FS bands.

use minixrs_ipc::ipc_sendrec;
use minixrs_kernel_shared::callnr::{SYS_COPY, SYS_SAFECOPY};
use minixrs_kernel_shared::com::{SYSTEM, boot_endpoint};
use minixrs_kernel_shared::error::OK;
use minixrs_kernel_shared::{Endpoint, Message};

use crate::payload::{wr_i32, wr_u64};

/// `SYS_SAFECOPY` — copy between the range grant `gid` describes and the
/// caller's own buffer at `addr`.
///
/// `direction` is `SAFECOPY_FROM` (grant → caller) or `SAFECOPY_TO` (caller →
/// grant); `offset` is measured within the granted range, so a client can drive a
/// short-write loop by advancing it. `granter` must be the endpoint the *kernel*
/// stamped on the request being served — see the module docs.
///
/// Returns the kernel-call result: `OK`, or a negative errno. Callers should relay
/// a negative result **verbatim** rather than collapsing it, because the two
/// failures mean different things to the client: `EPERM` is "your grant does not
/// authorize this" and `EFAULT` is "your buffer is not mapped".
pub fn sys_safecopy(
    direction: i32,
    granter: Endpoint,
    gid: i32,
    offset: u64,
    addr: u64,
    bytes: u64,
) -> i32 {
    let mut m = Message {
        m_source: 0,
        m_type: SYS_SAFECOPY,
        payload: [0u8; 96],
    };
    wr_i32(&mut m, 0, direction);
    wr_i32(&mut m, 4, granter);
    wr_i32(&mut m, 8, gid);
    wr_u64(&mut m, 16, offset);
    wr_u64(&mut m, 24, addr);
    wr_u64(&mut m, 32, bytes);
    sendrec_to_system(&mut m)
}

/// `SYS_COPY` — raw privileged copy from `(src_e, src_addr)` to
/// `(dst_e, dst_addr)`, with no grant involved. `SELF` names the caller.
///
/// There is no per-target authorization here at all: the caller's `k_call_mask`
/// bit *is* the whole check, the `SYS_VMCTL` trust stance. Only for small
/// control-plane reads on behalf of a caller the server already trusts.
pub fn sys_copy(
    src_e: Endpoint,
    src_addr: u64,
    dst_e: Endpoint,
    dst_addr: u64,
    bytes: u64,
) -> i32 {
    let mut m = Message {
        m_source: 0,
        m_type: SYS_COPY,
        payload: [0u8; 96],
    };
    wr_i32(&mut m, 0, src_e);
    wr_i32(&mut m, 4, dst_e);
    wr_u64(&mut m, 16, src_addr);
    wr_u64(&mut m, 24, dst_addr);
    wr_u64(&mut m, 32, bytes);
    sendrec_to_system(&mut m)
}

/// SENDREC a prepared kernel call to `SYSTEM` and flatten the two failure routes.
///
/// A trap-level failure (the SENDREC itself was refused — no `ipc_to` bit, bad
/// endpoint) and a call-level failure (the kernel ran the call and rejected it)
/// arrive by different paths, so both are checked; the same two-step every other
/// `server-rt` client uses.
fn sendrec_to_system(m: &mut Message) -> i32 {
    let trap_rc = ipc_sendrec(boot_endpoint(SYSTEM), m);
    if trap_rc != OK {
        return trap_rc;
    }
    m.m_type
}

