const DIAG_LINE_MAX: usize = 88;

/// A `core::fmt::Write` sink over a fixed stack buffer.
#[cfg_attr(test, allow(dead_code))]
struct DiagBuf {
    buf: [u8; DIAG_LINE_MAX],
    len: usize,
}

impl DiagBuf {
