// SPDX-License-Identifier: BSD-3-Clause
// Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors
//! `CDEV_WRITE` request parsing and validation — the driver's pure logic.
//!
//! Everything here is a total function over a [`Message`], so it carries the
//! crate's unit tests. The IPC round-trip and the volatile MMIO stores live in
//! `main.rs` and `pl011.rs` respectively, and are verified through the boot log.
//! Same split as `servers/ds`'s `registry.rs` / `main.rs`.
//!
//! ## Two things this module is careful about
//!
//! **The granter is not here.** [`parse_write`] reads only the four payload
//! fields; the granter comes from the kernel-stamped `m_source`, which the caller
//! passes straight to `SYS_SAFECOPY`. A granter *field* would make any
//! grant-holding driver a confused deputy, aiming a privileged cross-address-space
//! copy wherever its client pointed. There is deliberately no way to express one
//! through this API.
//!
//! **An over-long request is a short write, not an error.** [`validate_write`]
//! clamps to [`CDEV_MAX_IO`] and reports the clamped count; the client re-sends
//! with `offset` advanced. That is POSIX `write()`'s contract, and it is what lets
//! the driver stage through a fixed buffer in its `main` frame with no allocator.

use minixrs_kernel_shared::Message;
use minixrs_kernel_shared::callnr::{
    CDEV_GRANT_OFF, CDEV_LEN_OFF, CDEV_MAX_IO, CDEV_MINOR_CONSOLE, CDEV_MINOR_OFF,
    CDEV_OFFSET_OFF,
};
use minixrs_kernel_shared::error::{EINVAL, ENXIO};
use minixrs_kernel_shared::grant::grant_valid;
use minixrs_server_rt::{rd_i32, rd_u64};

/// A parsed `CDEV_WRITE` request. Field-for-field the payload, with no
/// interpretation applied — [`validate_write`] does that.
#[derive(Copy, Clone, PartialEq, Eq, Debug)]
pub struct WriteRequest {
    /// Device minor. Only [`CDEV_MINOR_CONSOLE`] exists today.
    pub minor: i32,
    /// Grant id naming the client's source buffer. Must carry `CPF_READ` and name
    /// this driver as grantee — both checked by the kernel, not here.
    pub gid: i32,
    /// Bytes the client asked to write. May exceed [`CDEV_MAX_IO`].
    pub len: i32,
    /// Offset within the granted range to start at. Advanced by the client across
    /// a short-write loop; range-checked against the grant by the kernel.
    pub offset: u64,
}

/// Read a `CDEV_WRITE` request out of a message payload.
///
/// Total: every field is a fixed-offset scalar read that cannot fail (`server-rt`'s
/// accessors return `0` for an out-of-range offset), so a malformed request becomes
/// an invalid *value* that [`validate_write`] rejects, never a panic.
pub fn parse_write(msg: &Message) -> WriteRequest {
    WriteRequest {
        minor: rd_i32(msg, CDEV_MINOR_OFF),
        gid: rd_i32(msg, CDEV_GRANT_OFF),
        len: rd_i32(msg, CDEV_LEN_OFF),
        offset: rd_u64(msg, CDEV_OFFSET_OFF),
    }
}

/// Decide how many bytes to move for `req`, or which errno to reply.
///
/// `Ok(n)` means "copy `n` bytes and reply `n`" — including `Ok(0)`, which is a
/// legal zero-length write that needs no copy at all. `Err(e)` is a negative errno
/// for the reply.
///
/// The checks, in the order a driver should apply them:
///
/// 1. `minor != CDEV_MINOR_CONSOLE` → `ENXIO`. Slice 5.11's `/dev/null` and
///    `/dev/zero` become additional minors here.
/// 2. `len < 0` → `EINVAL`. A negative length would otherwise widen into a huge
///    `u64` byte count for the kernel copy.
/// 3. An invalid grant id → `EINVAL`. Cheap local reject of the one value that can
///    never name a grant (`GRANT_INVALID`, and anything else negative); the kernel
///    still re-validates index, sequence, access, and grantee.
/// 4. `len == 0` → `Ok(0)`, checked *after* the gid so a zero-length write with a
///    garbage grant is still reported as the error it is.
/// 5. Otherwise clamp to [`CDEV_MAX_IO`].
pub fn validate_write(req: WriteRequest) -> Result<usize, i32> {
    if req.minor != CDEV_MINOR_CONSOLE {
        return Err(ENXIO);
    }
    if req.len < 0 {
        return Err(EINVAL);
    }
    if !grant_valid(req.gid) {
        return Err(EINVAL);
    }
    let len = req.len as usize;
    if len > CDEV_MAX_IO {
        return Ok(CDEV_MAX_IO);
    }
    Ok(len)
}

#[cfg(test)]
mod tests {
    use super::*;
    use minixrs_kernel_shared::grant::{GRANT_INVALID, grant_id};
    use minixrs_server_rt::{wr_i32, wr_u64};

    /// Build a well-formed `CDEV_WRITE` payload. The `granter` is deliberately not
    /// a parameter — there is no field for it.
    fn request(minor: i32, gid: i32, len: i32, offset: u64) -> Message {
        let mut m = Message {
            m_source: 0,
            m_type: 0,
            payload: [0u8; 96],
        };
        wr_i32(&mut m, CDEV_MINOR_OFF, minor);
        wr_i32(&mut m, CDEV_GRANT_OFF, gid);
        wr_i32(&mut m, CDEV_LEN_OFF, len);
        wr_u64(&mut m, CDEV_OFFSET_OFF, offset);
        m
    }

    const GOOD_GID: i32 = grant_id(3, 1);

    #[test]
    fn parse_reads_every_field_from_its_own_offset() {
        // Four distinct values, so a swapped pair of offsets would fail.
        let m = request(0, GOOD_GID, 64, 4096);
        assert_eq!(
            parse_write(&m),
            WriteRequest {
                minor: 0,
                gid: GOOD_GID,
                len: 64,
                offset: 4096,
            }
        );
    }

    #[test]
    fn parse_of_a_zeroed_payload_yields_a_rejectable_request() {
        // A client that sent nothing at all: minor 0 happens to be the console,
        // but grant id 0 has sequence 0 and index 0, and length 0 is a no-op. The
        // point is that nothing panics and nothing copies.
        let m = Message {
            m_source: 0,
            m_type: 0,
            payload: [0u8; 96],
        };
        let req = parse_write(&m);
        assert_eq!(req.len, 0);
        assert_eq!(validate_write(req), Ok(0));
    }

    #[test]
    fn a_normal_write_passes_its_length_through() {
        for len in [1i32, 12, 64, CDEV_MAX_IO as i32 - 1, CDEV_MAX_IO as i32] {
            let req = parse_write(&request(CDEV_MINOR_CONSOLE, GOOD_GID, len, 0));
            assert_eq!(validate_write(req), Ok(len as usize), "len {len}");
        }
    }

    #[test]
    fn an_over_long_write_is_clamped_not_refused() {
        // The short-write contract: the driver moves what it can and *reports* it,
        // so the client can advance `offset` and come back. A refusal here would
        // make every write longer than 256 bytes impossible.
        for len in [
            CDEV_MAX_IO as i32 + 1,
            CDEV_MAX_IO as i32 * 2,
            4096,
            i32::MAX,
        ] {
            assert_eq!(
                validate_write(parse_write(&request(
                    CDEV_MINOR_CONSOLE,
                    GOOD_GID,
                    len,
                    0
                ))),
                Ok(CDEV_MAX_IO),
                "len {len}"
            );
        }
    }

    #[test]
    fn a_zero_length_write_is_ok_not_an_error() {
        let req = parse_write(&request(CDEV_MINOR_CONSOLE, GOOD_GID, 0, 0));
        assert_eq!(validate_write(req), Ok(0));
    }

    #[test]
    fn an_unknown_minor_is_enxio() {
        for minor in [1i32, 7, -1, i32::MAX] {
            let req = parse_write(&request(minor, GOOD_GID, 16, 0));
            assert_eq!(validate_write(req), Err(ENXIO), "minor {minor}");
        }
    }

    #[test]
    fn a_negative_length_is_einval() {
        // Left unchecked this would widen into a ~16 EiB `u64` byte count for the
        // kernel copy call.
        for len in [-1i32, -256, i32::MIN] {
            let req = parse_write(&request(CDEV_MINOR_CONSOLE, GOOD_GID, len, 0));
            assert_eq!(validate_write(req), Err(EINVAL), "len {len}");
        }
    }

    #[test]
    fn an_invalid_grant_id_is_einval() {
        for gid in [GRANT_INVALID, -2, i32::MIN] {
            let req = parse_write(&request(CDEV_MINOR_CONSOLE, gid, 16, 0));
            assert_eq!(validate_write(req), Err(EINVAL), "gid {gid}");
        }
    }

    /// Check order matters: a request that is wrong in two ways must report the
    /// *first* problem, so a client fixing one error learns about the next.
    #[test]
    fn the_minor_check_precedes_the_length_and_grant_checks() {
        let req = parse_write(&request(9, GRANT_INVALID, -5, 0));
        assert_eq!(validate_write(req), Err(ENXIO));

        // ...and a bad grant is reported even on a zero-length write, rather than
        // being masked by the `Ok(0)` fast path.
        let req = parse_write(&request(CDEV_MINOR_CONSOLE, GRANT_INVALID, 0, 0));
        assert_eq!(validate_write(req), Err(EINVAL));
    }

    /// The offset is passed through untouched: range-checking it is the kernel's
    /// job (`verify_grant` tests `offset + bytes <= grant.len`), and clamping or
    /// rejecting it here would break the short-write loop the client drives with it.
    #[test]
    fn the_offset_is_passed_through_unvalidated() {
        for offset in [0u64, 1, 256, u64::MAX] {
            let req = parse_write(&request(CDEV_MINOR_CONSOLE, GOOD_GID, 16, offset));
            assert_eq!(req.offset, offset);
            assert_eq!(validate_write(req), Ok(16));
        }
    }
}

// SPDX-License-Identifier: BSD-3-Clause
// Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors
//! PL011 UART transmit, from EL0 (slice 5.3, decision D1).
//!
//! This is the whole reason minix.rs has a TTY *driver* rather than a TTY
//! *server*: the register accesses below are the first hardware the kernel does
//! not own. The kernel pre-maps the controller's MMIO page into this process's
//! address space at [`TTY_UART_VA`] with Device attributes while building it (see
//! `arch::aarch64::userland::load_boot_server`), because D1 deferred a
//! VM-mediated `VMCTL_MAP_PHYS` to Phase 6 — a driver has no way to ask for a
//! physical mapping yet.
//!
//! **TX only, polled, no interrupts.** RX needs `SYS_IRQCTL` and an interrupt
//! path, which is Phase 6. Polling `FR.TXFF` before each `DR` store is the
//! documented send sequence (ARM PL011 TRM r1p5 §3.3).
//!
//! ## Register offsets are deliberately re-declared
//!
//! `kernel/src/arch/aarch64/uart.rs` declares the same three constants. They are
//! not shared, and cannot be: the kernel crate is bare-metal-only and pinned to
//! `aarch64-unknown-none` by `forced-target`, so it can never be a dependency of a
//! user-space crate. Moving them into `kernel-shared` was considered and rejected —
//! a PL011 register layout is not a shared *ABI*, it is a hardware fact that two
//! independent drivers happen to both know. The duplication is noted in both files.
//!
//! ## Why this is the crate's only `unsafe`
//!
//! Everything else in the driver is message parsing (`cdev.rs`) or IPC through
//! `minix-ipc`. The two volatile accesses here are what `#![forbid(unsafe_code)]`
//! on `server-rt` exists to keep out of shared code.

use core::ptr::{read_volatile, write_volatile};

use minixrs_kernel_shared::uspace::TTY_UART_VA;

/// Data register — a byte written here is transmitted.
const DR_OFFSET: u64 = 0x00;
/// Flag register.
const FR_OFFSET: u64 = 0x18;
/// `FR` bit 5: transmit FIFO full. Poll until clear before storing to `DR`.
const FR_TXFF: u32 = 1 << 5;

/// Transmit one byte, blocking while the TX FIFO is full.
///
/// Under QEMU's TCG the FIFO never actually fills, so the poll is not observably
/// load-bearing here — it is correctness for real hardware, where dropping it
/// silently loses characters under load.
pub fn putc(c: u8) {
    let fr = (TTY_UART_VA + FR_OFFSET) as *mut u32;
    let dr = (TTY_UART_VA + DR_OFFSET) as *mut u32;
    // SAFETY: `TTY_UART_VA` is mapped into this process's address space by the
    // kernel at boot — one page, `Prot::DEVICE_RW` (EL0 read+write, never
    // executable, Device memory), covering the PL011's whole register block. TTY
    // is the only process with that mapping, and this process is single-threaded
    // with no signal handlers, so there is no concurrent access to order against.
    // Volatile is required in both directions: the compiler must not cache `FR`
    // across the poll (it would spin forever) or elide/duplicate the `DR` store
    // (each store transmits one character).
    unsafe {
        while read_volatile(fr) & FR_TXFF != 0 {}
        write_volatile(dr, c as u32);
    }
}

/// Transmit `bytes`, translating LF to CRLF.
///
/// The serial console is a terminal, not a file: a bare LF moves down a line
/// without returning the carriage, so output staircases. Translating here rather
/// than in the client keeps every writer honest — and matches what the kernel's
/// own `Pl011: fmt::Write` impl already does, so kernel traces and EL0 text
/// interleave without one of them looking broken.
///
/// (`grep -aF` markers cannot express `\r`, so the boot log cannot prove this
/// arm; it is verified by the console being readable.)
pub fn write(bytes: &[u8]) {
    for &b in bytes {
        if b == b'\n' {
            putc(b'\r');
        }
        putc(b);
    }
}

