37	/// Perform the SEF startup handshake: learn the server's own endpoint and name
38	/// from the kernel via `SYS_GETINFO(GET_WHOAMI)` (a SENDREC to `SYSTEM`), then
39	/// run the registered fresh-init callback. Returns the [`Sef`] handle to drive
40	/// the receive loop, or a negative error code if the handshake or init failed.
41	pub fn sef_startup(cfg: SefConfig) -> Result<Sef, i32> {
42	    // SYS_GETINFO(GET_WHOAMI): request selector goes in payload[0..4]; the
43	    // kernel replies in-place with our endpoint (0..4), priv flags (4..8),
44	    // init flags (8..12), and name (12..28), setting m_type = OK.
45	    let mut msg = Message {
46	        m_source: 0,
47	        m_type: SYS_GETINFO,
48	        payload: [0u8; 96],
49	    };
50	    msg.payload[0..4].copy_from_slice(&GET_WHOAMI.to_ne_bytes());
51	
52	    let trap_rc = ipc_sendrec(boot_endpoint(SYSTEM), &mut msg);
53	    if trap_rc != OK {
54	        return Err(trap_rc);
55	    }
56	    if msg.m_type != OK {
57	        return Err(msg.m_type);
58	    }
59	
60	    let endpoint = i32::from_ne_bytes(
61	        msg.payload[0..4]
62	            .try_into()
63	            .expect("payload is at least 4 bytes"),
64	    );
65	    let mut name = [0u8; SYS_GETINFO_NAME_LEN];
66	    name.copy_from_slice(&msg.payload[12..12 + SYS_GETINFO_NAME_LEN]);
67	
68	    let sef = Sef {
69	        endpoint,
70	        name,
71	        signal_handler: cfg.signal_handler,
72	    };
