124	                    // unwired, so the ack would return `ECALLDENIED` — harmless
125	                    // while the heartbeat is dormant, but the wiring must land
126	                    // with the heartbeat or RS will conclude the server is dead.
127	                    let _ = ipc_notify(boot_endpoint(RS_PROC_NR));
128	                }
129	                SefEvent::Signal(signo) => {
130	                    if let Some(handler) = self.signal_handler {
131	                        handler(signo);
132	                    }
133	                }
